/* From Uiverse.io by vinodjangid07 - Tags: button, add, hover effect, add to cart */
.__UIV_SCOPE__ .CartBtn {
  width: 140px;
  height: 40px;
  border-radius: 12px;
  border: none;
  background-color: rgb(255, 208, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition-duration: .5s;
  overflow: hidden;
  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.103);
  position: relative;
}

.__UIV_SCOPE__ .IconContainer {
  position: absolute;
  left: -50px;
  width: 30px;
  height: 30px;
  background-color: transparent;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  z-index: 2;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .icon {
  border-radius: 1px;
}

.__UIV_SCOPE__ .text {
  height: 100%;
  width: fit-content;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgb(17, 17, 17);
  z-index: 1;
  transition-duration: .5s;
  font-size: 1.04em;
  font-weight: 600;
}

.__UIV_SCOPE__ .CartBtn:hover .IconContainer {
  transform: translateX(58px);
  border-radius: 40px;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .CartBtn:hover .text {
  transform: translate(10px,0px);
  transition-duration: .5s;
}

.__UIV_SCOPE__ .CartBtn:active {
  transform: scale(0.95);
  transition-duration: .5s;
}
